#include <mavsdk/mavsdk.h>
#include <mavsdk/plugins/mavlink_direct/mavlink_direct.h>
#include <mavsdk/mavlink_address.h>

#include <iostream>
#include <chrono>
#include <thread>
#include <memory>

using namespace std::chrono_literals;
using namespace mavsdk;

void usage(const std::string &bin_name)
{
    std::cerr << "Usage : " << bin_name << " <connection_url>\n"
              << "Connection URL format should be :\n"
              << " For TCP server: tcpin://<our_ip>:<port>\n"
              << " For TCP client: tcpout://<remote_ip>:<port>\n"
              << " For UDP server: udp://<our_ip>:<port>\n"
              << " For UDP client: udp://<remote_ip>:<port>\n"
              << " For Serial : serial://</path/to/serial/dev>:<baudrate>]\n"
              << "For example, to connect to the simulator use URL: udpin://0.0.0.0:14540\n";
}

int main(int argc, char *argv[])
{
    if (argc != 2)
    {
        usage(argv[0]);
        return 1;
    }

    float_t msg_counter = 0.0f;

    uint8_t drone_system_id = 10;
    uint8_t drone_component_id = 2;
    bool always_send_heartbeat = true;

    Mavsdk::Configuration config = Mavsdk::Configuration(drone_system_id, drone_component_id, always_send_heartbeat);

    // create mavsdk instance
    Mavsdk mavsdk_drone{config};

    // create a system
    std::shared_ptr<mavsdk::System> peer_system_;

    // Connect using the provided connection URL
    std::string conn_url = argv[1];
    auto connection_result = mavsdk_drone.add_any_connection(conn_url);

    while (connection_result != ConnectionResult::Success)
    {
        std::this_thread::sleep_for(std::chrono::seconds(1));
        connection_result = mavsdk_drone.add_any_connection(conn_url);
    }

    std::cout << "connected to the local serial radio at " << conn_url << std::endl;

    int counter = 0;
    while (mavsdk_drone.systems().size() == 0)
    {
        std::cout << counter++ << "-trying to detect a peer system..." << std::endl;
        std::this_thread::sleep_for(std::chrono::milliseconds(1000));
    }

    std::cout << "peer system detected... " << std::endl;

    // Get the first connected system
    peer_system_ = mavsdk_drone.systems()[0];
    if (!peer_system_->is_connected())
    {
        std::cerr << "peer system not connected!" << std::endl;
        return 1;
    }
    else
    {
        std::cout << "peer system connected!" << std::endl;
    }

    auto mavlink_direct = MavlinkDirect{peer_system_};

    std::string custom_xml = R"(
    <mavlink>
        <messages>
            <message id="42000" name="MY_DRONE_GLOBAL_POSITION">
                <field type="float" name="latitude">latitude</field>
                <field type="float" name="longitude">longitude</field>
                <field type="float" name="altitude">altitude</field>
            </message>
        </messages>
    </mavlink>)";

    // Load custom XML
    MavlinkDirect::Result xml_result = mavlink_direct.load_custom_xml(custom_xml);

    if (xml_result != MavlinkDirect::Result::Success)
    {
        std::cerr << "Failed to load custom XML: " << xml_result << std::endl;
        return 1;
    }

    MavlinkDirect::MavlinkMessage my_drone_global_position{};
    my_drone_global_position.message_name = "END_TELEMETRY";
    my_drone_global_position.system_id = drone_system_id;
    my_drone_global_position.component_id = drone_component_id;
    my_drone_global_position.target_system_id = 250;
    my_drone_global_position.target_component_id = 1;

    while (true)
    {

        // fill out the message
        my_drone_global_position.fields_json =
            R"({"latitude": )" + std::to_string(msg_counter) +
            R"(,"longitude": )" + std::to_string(msg_counter) +
            R"(,"altitude": )" + std::to_string(msg_counter) +
            R"(})";

        auto result_hb = mavlink_direct.send_message(end_telemetry);

        if (result_hb == MavlinkDirect::Result::Success)
        {
            std::cout << "telemetry message " << (msg_counter + 1) << " sent successfully" << std::endl;
        }
        else
        {
            std::cerr << " telemetry message could not be sent: " << result_hb << std::endl;
        }

        msg_counter++;

        // 1Hz
        std::this_thread::sleep_for(std::chrono::milliseconds(1000));
    }

    return 0;
}
